CREATE TABLE public.triage_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80), owner_id uuid NOT NULL, invite_code uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.triage_workspaces TO authenticated; GRANT ALL ON public.triage_workspaces TO service_role;
ALTER TABLE public.triage_workspaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.triage_members (workspace_id uuid NOT NULL REFERENCES public.triage_workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL, PRIMARY KEY(workspace_id,user_id));
GRANT SELECT ON public.triage_members TO authenticated; GRANT ALL ON public.triage_members TO service_role;
ALTER TABLE public.triage_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_triage_member(wid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.triage_members WHERE workspace_id=wid AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_triage_member(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_triage_member(uuid) TO authenticated;
CREATE POLICY members_self ON public.triage_members FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY workspace_member ON public.triage_workspaces FOR SELECT TO authenticated USING(public.is_triage_member(id));
CREATE TABLE public.triage_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.triage_workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL, mode text NOT NULL CHECK(mode IN ('demo','backend','cloud')), log text NOT NULL CHECK(char_length(log)<=50000), diagnosis jsonb NOT NULL, tags text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.triage_reports TO authenticated; GRANT ALL ON public.triage_reports TO service_role;
ALTER TABLE public.triage_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_read ON public.triage_reports FOR SELECT TO authenticated USING(public.is_triage_member(workspace_id));
CREATE POLICY report_create ON public.triage_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_triage_member(workspace_id));
CREATE POLICY report_delete ON public.triage_reports FOR DELETE TO authenticated USING(user_id=auth.uid() AND public.is_triage_member(workspace_id));
CREATE INDEX triage_reports_workspace_date ON public.triage_reports(workspace_id,created_at DESC);
CREATE TABLE public.triage_webhooks (workspace_id uuid NOT NULL REFERENCES public.triage_workspaces(id) ON DELETE CASCADE, provider text NOT NULL CHECK(provider IN ('teams','slack')), url text NOT NULL, PRIMARY KEY(workspace_id,provider));
GRANT ALL ON public.triage_webhooks TO service_role;
ALTER TABLE public.triage_webhooks ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.create_triage_workspace(workspace_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; INSERT INTO public.triage_workspaces(name,owner_id) VALUES(trim(workspace_name),auth.uid()) RETURNING id INTO wid; INSERT INTO public.triage_members VALUES(wid,auth.uid()); RETURN wid; END $$;
CREATE FUNCTION public.join_triage_workspace(code uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT id INTO wid FROM public.triage_workspaces WHERE invite_code=code; IF wid IS NULL THEN RAISE EXCEPTION 'Invalid invitation'; END IF; INSERT INTO public.triage_members VALUES(wid,auth.uid()) ON CONFLICT DO NOTHING; RETURN wid; END $$;
REVOKE ALL ON FUNCTION public.create_triage_workspace(text),public.join_triage_workspace(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_triage_workspace(text),public.join_triage_workspace(uuid) TO authenticated;
COMMENT ON TABLE public.triage_webhooks IS 'Server-only channel secrets; endpoints never returned to browsers.';